const HOYMILES_EMS_SHARED_INPUTS_C4_FULL_BINDINGS = Object.freeze([
  "inverter_power_helper_entity",
  "forecast_today_helper_entity",
  "forecast_tomorrow_helper_entity",
  "forecast_day_3_helper_entity",
  "fallback_load_helper_entity",
]);

class HoymilesEmsSharedInputsCard extends HTMLElement {
  constructor() {
    super();
    this.attachShadow({ mode: "open" });
    this._config = null;
    this._hass = null;
    this._mounted = false;
    this._refs = {};
    this._listeners = [];
  }

  setConfig(config) {
    const mode = config?.mode === "summary" ? "summary" : "full";
    if (!config?.shared_inputs_entity) {
      throw new Error("shared_inputs_entity is required");
    }
    if (mode === "full") {
      const missing = HOYMILES_EMS_SHARED_INPUTS_C4_FULL_BINDINGS.filter(
        (key) => !config[key]
      );
      if (missing.length) throw new Error(`Missing full-view bindings: ${missing.join(", ")}`);
    }
    this._config = {
      load_diagnostics_entity: "sensor.hoymiles_hit_rce_optimized_plan",
      ...config,
      mode,
    };
    this._mount();
    this._patch();
  }

  set hass(value) {
    this._hass = value;
    this._patch();
  }

  getCardSize() {
    return this._config?.mode === "summary" ? 2 : 10;
  }

  _element(tag, className = "", text = null) {
    const node = document.createElement(tag);
    node.className = className;
    if (text !== null) node.textContent = text;
    return node;
  }

  _listen(node, type, listener) {
    node.addEventListener(type, listener);
    this._listeners.push([node, type, listener]);
  }

  _fact(parent, key) {
    const item = this._element("div", "shared-fact");
    item.dataset.fact = key;
    const label = this._element("span", "shared-label");
    const value = this._element("strong", "shared-value");
    const note = this._element("small", "shared-note");
    item.append(label, value, note);
    parent.append(item);
    this._refs.facts[key] = { item, label, value, note };
    return this._refs.facts[key];
  }

  _section(parent, key) {
    const section = this._element("section", "shared-section");
    section.dataset.section = key;
    const heading = this._element("h2");
    const grid = this._element("div", "shared-grid");
    section.append(heading, grid);
    parent.append(section);
    this._refs.sections[key] = { section, heading, grid };
    return this._refs.sections[key];
  }

  _mount() {
    if (this._mounted || !this._config) return;
    this._refs = {
      facts: {},
      sections: {},
      controls: {},
      readiness: {},
      expertFields: {},
    };
    const style = this._element("style");
    style.textContent = `
      ${HOYMILES_AURORA_THEME_CSS}
      :host { display: block; min-width: 0; }
      ha-card { background: var(--hoymiles-aurora-surface); border: 1px solid var(--hoymiles-aurora-border); border-radius: var(--ha-card-border-radius); box-shadow: var(--hoymiles-aurora-shadow); display: block; container-type: inline-size; overflow: hidden; color: var(--primary-text-color); }
      .shared-shell { padding: clamp(16px, 3vw, 28px); min-width: 0; }
      .shared-header { display: flex; align-items: flex-start; justify-content: space-between; gap: 16px; margin-bottom: 18px; }
      h1, h2, p { margin: 0; }
      h1 { font-size: clamp(1.35rem, 3vw, 2rem); }
      h2 { font-size: 1.05rem; margin-bottom: 12px; }
      .shared-subtitle, .shared-note, .shared-help { color: var(--secondary-text-color); overflow-wrap: anywhere; }
      .shared-subtitle { margin-top: 6px; max-width: 72ch; }
      .shared-sections { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 14px; }
      .shared-section, .shared-summary {
        min-width: 0; padding: 16px; border-radius: 16px;
        border: 1px solid color-mix(in srgb, var(--divider-color) 72%, #3ea6ff 28%);
        background: color-mix(in srgb, var(--card-background-color) 94%, #3ea6ff 6%);
      }
      .shared-grid, .shared-summary-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 10px; }
      .shared-fact { min-width: 0; padding: 10px 12px; border-radius: 12px; background: color-mix(in srgb, var(--card-background-color) 90%, var(--primary-text-color) 10%); }
      .shared-label, .shared-value, .shared-note { display: block; min-width: 0; overflow-wrap: anywhere; }
      .shared-label { font-size: .76rem; color: var(--secondary-text-color); }
      .shared-value { margin-top: 3px; font-size: clamp(.95rem, 2vw, 1.12rem); }
      .shared-note { min-height: 1.1em; margin-top: 4px; font-size: .72rem; }
      .shared-controls, .shared-expert-grid { display: grid; gap: 10px; margin-top: 12px; }
      .shared-control { display: grid; gap: 5px; min-width: 0; }
      input, select, button {
        box-sizing: border-box; min-height: 44px; max-width: 100%; border-radius: 11px;
        border: 1px solid var(--divider-color); padding: 8px 10px;
        color: var(--primary-text-color); background: var(--card-background-color); font: inherit;
      }
      button { cursor: pointer; font-weight: 700; border-color: color-mix(in srgb, #3ea6ff 62%, var(--divider-color)); }
      button:disabled, input:disabled, select:disabled { opacity: .55; cursor: not-allowed; }
      details { margin-top: 12px; }
      summary { min-height: 44px; display: flex; align-items: center; cursor: pointer; font-weight: 700; }
      .shared-readiness { display: grid; gap: 7px; }
      .shared-ready-row {
        display: grid; grid-template-columns: 24px minmax(0, 1fr); gap: 8px;
        align-items: center; width: 100%; min-height: 38px; padding: 6px 8px;
        border: 0; text-align: start; background: transparent; font-weight: 600;
      }
      .shared-ready-row[data-ready="true"] .shared-ready-icon { color: var(--success-color, #2de083); }
      .shared-ready-row[data-ready="false"] .shared-ready-icon { color: var(--warning-color, #ffc857); }
      .shared-ready-row[data-ready="informational"] .shared-ready-icon { color: var(--hoymiles-aurora-grid); }
      .shared-providerless { color: var(--warning-color, #ffc857); }
      .shared-expert { grid-column: 1 / -1; }
      .shared-expert-row { display: grid; grid-template-columns: minmax(120px, .45fr) minmax(0, 1fr); gap: 10px; padding: 7px 0; border-bottom: 1px solid var(--divider-color); }
      .shared-expert-row dd, .shared-expert-row dt { margin: 0; min-width: 0; overflow-wrap: anywhere; }
      .shared-raw { max-height: 260px; overflow: auto; white-space: pre-wrap; overflow-wrap: anywhere; font: .75rem/1.45 monospace; }
      .shared-summary { display: grid; gap: 12px; }
      .shared-summary-header { display: flex; align-items: center; justify-content: space-between; gap: 10px; }
      .shared-summary-title { font-size: 1rem; }
      .shared-open { width: 100%; }
      [hidden] { display: none !important; }
      @container (max-width: 760px) {
        .shared-sections, .shared-grid, .shared-summary-grid { grid-template-columns: 1fr; }
      }
      @container (max-width: 390px) {
        .shared-shell { padding: 12px; }
        .shared-header { display: block; }
        .shared-section, .shared-summary { padding: 12px; }
        .shared-expert-row { grid-template-columns: 1fr; gap: 3px; }
      }
    `;
    const card = this._element("ha-card");
    const shell = this._element("article", "shared-shell");
    shell.dataset.mode = this._config.mode;
    card.append(shell);
    this.shadowRoot.replaceChildren(style, card);
    this._refs.card = card;
    this._refs.shell = shell;
    if (this._config.mode === "summary") this._mountSummary(shell);
    else this._mountFull(shell);
    this._mounted = true;
  }

  _mountSummary(shell) {
    const panel = this._element("section", "shared-summary");
    const header = this._element("div", "shared-summary-header");
    const title = this._element("h2", "shared-summary-title");
    const status = this._element("strong", "shared-summary-status");
    header.append(title, status);
    const grid = this._element("div", "shared-summary-grid");
    panel.append(header, grid);
    shell.append(panel);
    this._refs.summaryTitle = title;
    this._refs.summaryStatus = status;
    for (const key of ["forecast", "loadModel", "systemPower"]) this._fact(grid, key);
    const open = this._element("button", "shared-open");
    open.type = "button";
    panel.append(open);
    this._refs.open = open;
    this._listen(open, "click", () => {
      const path = String(this._config.settings_path || "ustawienia-ems").replace(/^\/+/, "");
      const pathname = window.location?.pathname || "/lovelace/start";
      const dashboardBase = pathname.replace(/\/[^/]*\/?$/, "") || "/lovelace";
      window.history?.pushState(null, "", `${dashboardBase}/${path}`);
      window.dispatchEvent?.(new Event("location-changed"));
    });
  }

  _mountFull(shell) {
    const header = this._element("header", "shared-header");
    const titleGroup = this._element("div");
    const title = this._element("h1");
    const subtitle = this._element("p", "shared-subtitle");
    titleGroup.append(title, subtitle);
    header.append(titleGroup);
    const sections = this._element("div", "shared-sections");
    shell.append(header, sections);
    Object.assign(this._refs, { title, subtitle, sections });

    const installation = this._section(sections, "installation");
    const inverterPowerControl = this._control(
      "select",
      "inverterPower",
      this._config.inverter_power_helper_entity
    );
    installation.section.insertBefore(inverterPowerControl.wrapper, installation.grid);
    for (const key of ["inverterModel", "inverterPower", "inverterCount", "systemPower", "battery", "bms"]) {
      this._fact(installation.grid, key);
    }

    const forecast = this._section(sections, "forecast");
    for (const key of ["today", "tomorrow", "day3", "remainingToday", "lastUpdate", "source"]) {
      this._fact(forecast.grid, key);
    }

    const load = this._section(sections, "loadModel");
    for (const key of ["loadReady", "historyDays", "nightHistory", "averageDaily", "weekdayProfile", "weekendProfile", "fallbackUsed"]) {
      this._fact(load.grid, key);
    }
    const fallback = this._control(
      "number",
      "fallback",
      this._config.fallback_load_helper_entity
    );
    fallback.input.step = "0.1";
    fallback.input.min = "0";
    const fallbackHelp = this._element("p", "shared-help");
    load.section.append(fallback.wrapper, fallbackHelp);
    this._refs.fallbackWrapper = fallback.wrapper;
    this._refs.fallbackHelp = fallbackHelp;

    const readiness = this._section(sections, "readiness");
    const readinessList = this._element("div", "shared-readiness");
    readiness.grid.append(readinessList);
    readiness.grid.style.setProperty("grid-template-columns", "1fr");
    for (const key of ["topology", "batteryBms", "pvForecast", "loadHistory", "physicalFlows", "gridBattery"]) {
      const row = this._element("button", "shared-ready-row");
      row.type = "button";
      row.dataset.readiness = key;
      row.dataset.target = {
        topology: "installation",
        batteryBms: "installation",
        pvForecast: "forecast",
        loadHistory: "loadModel",
        physicalFlows: "expert",
        gridBattery: "expert",
      }[key];
      const icon = this._element("span", "shared-ready-icon");
      const text = this._element("span");
      row.append(icon, text);
      readinessList.append(row);
      this._refs.readiness[key] = { row, icon, text };
    }

    const expert = this._element("details", "shared-section shared-expert");
    const expertSummary = this._element("summary");
    const expertSources = this._element("h3");
    const sourceControls = this._element("div", "shared-controls");
    for (const [key, entity] of [
      ["forecastToday", this._config.forecast_today_helper_entity],
      ["forecastTomorrow", this._config.forecast_tomorrow_helper_entity],
      ["forecastDay3", this._config.forecast_day_3_helper_entity],
    ]) {
      sourceControls.append(this._control("text", key, entity).wrapper);
    }
    const expertGrid = this._element("dl", "shared-expert-grid");
    for (const key of [
      "entryId", "forecastTodayEntity", "forecastTomorrowEntity", "forecastDay3Entity",
      "forecastRemainingEntity", "pvPowerEntity", "homeLoadPowerEntity", "systemLoadPowerEntity",
      "batteryPowerEntity", "gridPowerEntity", "gridToBatteryPowerEntity", "freshness",
      "provenance", "migration", "legacy",
    ]) {
      const row = this._element("div", "shared-expert-row");
      const term = this._element("dt");
      const value = this._element("dd");
      row.append(term, value);
      expertGrid.append(row);
      this._refs.expertFields[key] = { row, term, value };
    }
    const rawTitle = this._element("h3");
    const raw = this._element("pre", "shared-raw");
    expert.append(expertSummary, expertSources, sourceControls, expertGrid, rawTitle, raw);
    sections.append(expert);
    Object.assign(this._refs, { expert, expertSummary, expertSources, rawTitle, raw });
    this._listen(expert, "toggle", () => this._patchFallbackVisibility());
    for (const ref of Object.values(this._refs.readiness)) {
      this._listen(ref.row, "click", () => {
        const targetKey = ref.row.dataset.target;
        const target = targetKey === "expert"
          ? this._refs.expert
          : this._refs.sections[targetKey]?.section;
        if (targetKey === "expert") this._refs.expert.open = true;
        target?.scrollIntoView?.({ behavior: "smooth", block: "start" });
      });
    }
  }

  _control(type, key, entityId) {
    const wrapper = this._element("label", "shared-control");
    wrapper.dataset.control = key;
    const label = this._element("span", "shared-label");
    const input = this._element(type === "select" ? "select" : "input");
    if (type !== "select") input.type = type;
    wrapper.append(label, input);
    this._refs.controls[key] = { wrapper, label, input, entityId, type };
    const eventType = type === "text" ? "change" : "change";
    this._listen(input, eventType, () => this._writeControl(this._refs.controls[key]));
    return this._refs.controls[key];
  }

  async _writeControl(control) {
    if (!this._hass || !control?.entityId) return;
    const domain = control.entityId.split(".", 1)[0];
    const service = domain === "input_select" ? "select_option" : "set_value";
    const data = { entity_id: control.entityId };
    if (domain === "input_select") data.option = control.input.value;
    else data.value = control.type === "number" ? Number(control.input.value) : control.input.value;
    control.input.disabled = true;
    try {
      await this._hass.callService(domain, service, data);
    } finally {
      control.input.disabled = false;
    }
  }

  _language() {
    return String(this._hass?.language || document.documentElement?.lang || "en")
      .toLowerCase()
      .startsWith("pl") ? "pl" : "en";
  }

  _available(entity) {
    return Boolean(entity && !["unknown", "unavailable", "none", ""].includes(String(entity.state)));
  }

  _boolean(value) {
    return value === true;
  }

  _number(value, digits = 1) {
    const number = Number(value);
    return Number.isFinite(number)
      ? new Intl.NumberFormat(this._language(), { maximumFractionDigits: digits }).format(number)
      : null;
  }

  _energyFromEntity(entityId) {
    const entity = entityId ? this._hass?.states?.[entityId] : null;
    const value = this._number(entity?.state, 2);
    return value === null ? null : `${value} kWh`;
  }

  _sourceText(value, fallback, copy) {
    const normalized = String(value || "").trim().toLowerCase();
    if (!normalized) return fallback;
    if ([
      "auto", "automatic", "model_detected", "source_device",
      "source_device_model", "device_model", "rated_power_each_x_inverter_count",
      "derived_inverter_power_x_count", "automatic_candidate",
    ].includes(normalized)) return copy.automatic;
    if (normalized === "entry_local_registry") return fallback;
    if ([
      "physical_fc03", "inverter_readback", "number_of_machines_readback",
    ].includes(normalized)) return copy.inverterReadback;
    if ([
      "physical_capacity_register", "battery_capacity_readback",
      "capacity_register",
    ].includes(normalized)) return copy.capacityReadback;
    if (["physical_bms", "bms_fc03", "bms_readback"].includes(normalized)) {
      return copy.bmsReadback;
    }
    if (["configured_shared_helpers", "shared_forecast_helpers"].includes(normalized)) {
      return copy.sharedForecast;
    }
    if (normalized === "configured_shared_helper") return copy.sharedSetting;
    if (normalized === "mixed_sources") return copy.mixedForecastSources;
    if (["new_helper", "legacy_helper"].includes(normalized)) return copy.sharedForecast;
    if (["recorder_phase_energy_counters", "rce_recorder_broker"].includes(normalized)) {
      return copy.recorderHistory;
    }
    return value;
  }

  _qualityText(value, copy) {
    const normalized = String(value || "").trim().toLowerCase();
    if (!normalized) return "";
    if (normalized === "complete") return copy.completeData;
    return value;
  }

  _dateTime(value) {
    const parsed = Date.parse(value || "");
    if (!Number.isFinite(parsed)) return null;
    return new Intl.DateTimeFormat(this._language(), {
      dateStyle: "short",
      timeStyle: "medium",
    }).format(new Date(parsed));
  }

  _qualityDate(value) {
    if (!/^\d{4}-\d{2}-\d{2}$/.test(String(value || ""))) return null;
    const parsed = new Date(`${value}T12:00:00Z`);
    if (!Number.isFinite(parsed.getTime())) return null;
    return new Intl.DateTimeFormat(this._language(), {
      day: "2-digit",
      month: "2-digit",
    }).format(parsed);
  }

  _loadCoverageNote(attributes, copy, kind) {
    if (!attributes) return copy.qualificationUnknown;
    const isNight = kind === "night";
    const count = Number(
      isNight
        ? attributes.recorder_night_history_days
        : attributes.recorder_load_history_days
    );
    const reason = String(
      isNight
        ? attributes.recorder_night_qualification_reason
        : attributes.recorder_load_qualification_reason
    ).trim();
    const date = this._qualityDate(
      isNight
        ? attributes.recorder_night_qualification_date
        : attributes.recorder_load_qualification_date
    );
    if (Number.isFinite(count) && count > 0 && reason === "complete") return "";
    const prefix = isNight ? copy.noFullNights : copy.noFullDays;
    if ((!reason || reason === "unknown") && isNight) {
      const readStatus = String(attributes.load_history_read_status || "");
      if (["short_complete", "extended_complete", "completed_night_added"].includes(readStatus)) {
        return `${prefix} — ${copy.collectingWindow}`;
      }
    }
    if (!reason || reason === "unknown") return `${prefix} — ${copy.qualificationUnknown}`;
    const phaseRows = attributes.recorder_load_phase_quality?.[
      attributes.recorder_load_qualification_date
    ];
    const phaseReasons = phaseRows && typeof phaseRows === "object"
      ? Object.values(phaseRows).map((value) => String(value))
      : [];
    if (!isNight && reason === "partial_phase_counter" && phaseReasons.includes("missing_start_edge")) {
      return `${prefix} — ${copy.missingDayStart}${date ? ` ${date}` : ""}`;
    }
    return `${prefix} — ${copy.rejectedWindow}: ${reason}${date ? ` (${date})` : ""}`;
  }

  _setFact(key, label, value, note = "") {
    const fact = this._refs.facts[key];
    if (!fact) return;
    fact.label.textContent = label;
    fact.value.textContent = value;
    fact.note.textContent = note;
  }

  _normalizeSharedContract(attributes) {
    if (
      Object.prototype.hasOwnProperty.call(
        attributes,
        "inverter_rated_power_each_kw"
      )
    ) {
      return { ...attributes, __raw: attributes };
    }
    const system = attributes.system || {};
    const forecast = attributes.forecast || {};
    const load = attributes.load || {};
    const bms = attributes.bms || {};
    const power = attributes.power || {};
    const migration = attributes.migration || {};
    const sample = (value) =>
      value && typeof value === "object" && !Array.isArray(value) ? value : {};
    const samples = {
      inverterPower: sample(system.inverter_rated_power_each_kw),
      inverterCount: sample(system.inverter_count),
      systemPower: sample(system.system_rated_power_kw),
      capacity: sample(system.battery_capacity_kwh),
      forecastToday: sample(forecast.today),
      forecastTomorrow: sample(forecast.tomorrow),
      forecastDay3: sample(forecast.day3),
      forecastRemaining: sample(forecast.remaining_today),
      fallback: sample(load.fallback_daily_home_load_kwh),
      bmsVoltage: sample(bms.voltage_v),
      bmsChargeCurrent: sample(bms.maximum_charge_current_a),
      bmsDischargeCurrent: sample(bms.maximum_discharge_current_a),
      bmsChargePower: sample(bms.maximum_charge_power_kw),
      bmsDischargePower: sample(bms.maximum_discharge_power_kw),
      pvPower: sample(power.pv_power_kw),
      homeLoadPower: sample(power.home_load_power_kw),
      systemLoadPower: sample(power.system_load_power_kw),
      batteryPower: sample(power.battery_power_kw),
      gridPower: sample(power.grid_power_kw),
      gridToBatteryPower: sample(power.grid_to_battery_power),
    };
    const bmsSamples = [
      samples.bmsVoltage,
      samples.bmsChargeCurrent,
      samples.bmsDischargeCurrent,
      samples.bmsChargePower,
      samples.bmsDischargePower,
    ];
    const physicalSamples = [
      samples.pvPower,
      samples.homeLoadPower,
      samples.systemLoadPower,
      samples.batteryPower,
      samples.gridPower,
    ];
    const forecastTimes = [
      samples.forecastToday.reported_at,
      samples.forecastTomorrow.reported_at,
      samples.forecastDay3.reported_at,
      samples.forecastRemaining.reported_at,
    ].filter((value) => Number.isFinite(Date.parse(value || "")));
    const latestForecast = forecastTimes.length
      ? new Date(Math.max(...forecastTimes.map((value) => Date.parse(value)))).toISOString()
      : null;
    const profileReady = (profile, days) =>
      Array.isArray(profile) && profile.length === 48 && Number(days) > 0;
    const sourceFreshness = Object.fromEntries(
      Object.entries(samples).map(([key, value]) => [key, {
        fresh: value.fresh === true,
        age_seconds: value.age_seconds ?? null,
        reason: value.reason || "unavailable",
      }])
    );
    const provenance = Object.fromEntries(
      Object.entries(samples).map(([key, value]) => [
        key,
        value.provenance || "unavailable",
      ])
    );
    return {
      __raw: attributes,
      schema_version: attributes.schema_version,
      config_entry_id: attributes.config_entry_id,
      inverter_model: null,
      inverter_model_source: samples.inverterPower.provenance,
      inverter_rated_power_each_kw: samples.inverterPower.value,
      inverter_rated_power_source: samples.inverterPower.provenance,
      inverter_count: samples.inverterCount.value,
      inverter_count_source: samples.inverterCount.provenance,
      system_rated_power_kw: samples.systemPower.value,
      system_rated_power_source: samples.systemPower.provenance,
      battery_capacity_kwh: samples.capacity.value,
      battery_capacity_source: samples.capacity.provenance,
      bms_ready: bmsSamples.every((value) => value.fresh === true),
      bms_provenance: bmsSamples.map((value) => value.provenance).filter(Boolean)[0],
      forecast_today_entity: samples.forecastToday.entity_id,
      forecast_tomorrow_entity: samples.forecastTomorrow.entity_id,
      forecast_day_3_entity: samples.forecastDay3.entity_id,
      forecast_remaining_today_entity: samples.forecastRemaining.entity_id,
      forecast_today_ready: samples.forecastToday.fresh === true,
      forecast_tomorrow_ready: samples.forecastTomorrow.fresh === true,
      forecast_day_3_ready: samples.forecastDay3.fresh === true,
      forecast_remaining_today_ready: samples.forecastRemaining.fresh === true,
      forecast_last_updated: latestForecast,
      forecast_quality:
        samples.forecastToday.fresh === true && samples.forecastTomorrow.fresh === true
          ? "current"
          : "unavailable",
      forecast_provenance: samples.forecastToday.provenance,
      load_model_ready: load.ready === true,
      load_model_source: load.source,
      load_history_days: load.daily_history_days,
      average_daily_home_load_kwh: load.average_daily_home_load_kwh,
      weekday_profile_ready: profileReady(
        load.weekday_profile_30m_kwh,
        load.weekday_profile_days
      ),
      weekend_profile_ready: profileReady(
        load.weekend_profile_30m_kwh,
        load.weekend_profile_days
      ),
      fallback_currently_used:
        load.fallback_currently_used === true ||
        String(load.source || "").includes("fallback"),
      physical_power_ready: physicalSamples.every((value) => value.fresh === true),
      physical_power_quality: physicalSamples.every((value) => value.fresh === true)
        ? "current"
        : "unavailable",
      pv_power_entity: samples.pvPower.entity_id,
      home_load_power_entity: samples.homeLoadPower.entity_id,
      system_load_power_entity: samples.systemLoadPower.entity_id,
      battery_power_entity: samples.batteryPower.entity_id,
      grid_power_entity: samples.gridPower.entity_id,
      grid_to_battery_power_entity: samples.gridToBatteryPower.entity_id,
      grid_to_battery_ready: power.grid_to_battery_ready === true,
      grid_to_battery_quality: samples.gridToBatteryPower.quality || "providerless",
      source_freshness: sourceFreshness,
      physical_power_freshness: sourceFreshness,
      physical_power_provenance: provenance,
      migration_version: migration.version,
      migration_result: migration.result,
      legacy_aliases: migration.legacy_aliases || null,
    };
  }

  _patch() {
    if (!this._mounted || !this._config || !this._hass) return;
    const language = this._language();
    const copy = HOYMILES_EMS_SHARED_INPUTS_C4_COPY[language];
    const broker = this._hass.states?.[this._config.shared_inputs_entity];
    const rawAttributes = broker?.attributes || {};
    const attributes = this._normalizeSharedContract(rawAttributes);
    const available = this._available(broker);
    const entryId = attributes.config_entry_id || null;
    this._refs.shell.lang = language;
    this._refs.shell.dataset.available = String(available);
    this._refs.shell.dataset.entryId = entryId || "unavailable";
    if (this._config.mode === "summary") {
      this._patchSummary(copy, available, attributes);
      return;
    }
    this._patchFull(copy, available, attributes);
  }

  _patchSummary(copy, available, attributes) {
    this._refs.summaryTitle.textContent = copy.shared;
    this._refs.summaryStatus.textContent = available ? copy.ready : copy.unavailable;
    const forecastReady = attributes.forecast_today_ready === true && attributes.forecast_tomorrow_ready === true;
    const loadDays = this._number(attributes.load_history_days, 0);
    const systemPower = this._number(attributes.system_rated_power_kw, 1);
    this._setFact("forecast", copy.forecast, forecastReady ? copy.ready : copy.unavailable);
    this._setFact(
      "loadModel",
      copy.loadModel,
      loadDays === null ? copy.unavailable : `${loadDays} ${copy.days}`
    );
    this._setFact(
      "systemPower",
      copy.systemPower,
      systemPower === null ? copy.unavailable : `${systemPower} kW`
    );
    this._refs.open.textContent = copy.open;
  }

  _patchFull(copy, available, attributes) {
    this._refs.title.textContent = copy.title;
    this._refs.subtitle.textContent = copy.subtitle;
    const sectionTitles = {
      installation: copy.installation,
      forecast: copy.forecast,
      loadModel: copy.loadModel,
      readiness: copy.commonReadiness,
    };
    for (const [key, title] of Object.entries(sectionTitles)) {
      this._refs.sections[key].heading.textContent = title;
    }
    this._refs.fallbackHelp.textContent = copy.fallbackHelp;
    this._refs.expertSummary.textContent = copy.expert;
    this._refs.expertSources.textContent = copy.expertSources;
    this._refs.rawTitle.textContent = copy.raw;

    const inverterPower = this._number(attributes.inverter_rated_power_each_kw, 1);
    const inverterCount = this._number(attributes.inverter_count, 0);
    const systemPower = this._number(attributes.system_rated_power_kw, 1);
    const capacity = this._number(attributes.battery_capacity_kwh, 1);
    this._setFact("inverterModel", copy.inverterModel, attributes.inverter_model || copy.unknown, this._sourceText(attributes.inverter_model_source, copy.automatic, copy));
    this._setFact("inverterPower", copy.inverterPower, inverterPower === null ? copy.unknown : `${inverterPower} kW`, this._sourceText(attributes.inverter_rated_power_source, copy.automatic, copy));
    this._setFact("inverterCount", copy.inverterCount, inverterCount ?? copy.unknown, this._sourceText(attributes.inverter_count_source, copy.inverterReadback, copy));
    this._setFact("systemPower", copy.systemPower, systemPower === null ? copy.unknown : `${systemPower} kW`, this._sourceText(attributes.system_rated_power_source, copy.automatic, copy));
    this._setFact("battery", copy.battery, capacity === null ? copy.unknown : `${capacity} kWh`, this._sourceText(attributes.battery_capacity_source, copy.capacityReadback, copy));
    this._setFact("bms", copy.bms, attributes.bms_ready === true ? copy.ready : copy.unavailable, this._sourceText(attributes.bms_provenance, copy.bmsReadback, copy));

    for (const [key, label, readyKey, entityKey] of [
      ["today", copy.today, "forecast_today_ready", "forecast_today_entity"],
      ["tomorrow", copy.tomorrow, "forecast_tomorrow_ready", "forecast_tomorrow_entity"],
      ["day3", copy.day3, "forecast_day_3_ready", "forecast_day_3_entity"],
      ["remainingToday", copy.remainingToday, "forecast_remaining_today_ready", "forecast_remaining_today_entity"],
    ]) {
      const value = this._energyFromEntity(attributes[entityKey]);
      this._setFact(
        key,
        label,
        value || (attributes[readyKey] === true ? copy.dataReady : copy.dataMissing),
        attributes[readyKey] === true ? copy.ready : copy.unavailable
      );
    }
    this._setFact("lastUpdate", copy.lastUpdate, this._dateTime(attributes.forecast_last_updated) || copy.unknown);
    this._setFact("source", copy.source, this._sourceText(attributes.forecast_provenance, copy.unknown, copy), this._qualityText(attributes.forecast_quality, copy));

    const loadDays = this._number(attributes.load_history_days, 0);
    const loadDiagnostics = this._hass.states?.[
      this._config.load_diagnostics_entity
    ]?.attributes;
    const nightDays = this._number(
      loadDiagnostics?.recorder_night_history_days,
      0
    );
    const average = this._number(attributes.average_daily_home_load_kwh, 2);
    this._setFact("loadReady", copy.loadReady, attributes.load_model_ready === true ? copy.ready : copy.unavailable, this._sourceText(attributes.load_model_source, "", copy));
    this._setFact(
      "historyDays",
      copy.historyDays,
      loadDays === null ? copy.unknown : `${loadDays} ${copy.days}`,
      this._loadCoverageNote(loadDiagnostics, copy, "day")
    );
    this._setFact(
      "nightHistory",
      copy.nightHistory,
      nightDays === null ? copy.unknown : `${nightDays} ${copy.days}`,
      this._loadCoverageNote(loadDiagnostics, copy, "night")
    );
    this._setFact("averageDaily", copy.averageDaily, average === null ? copy.unknown : `${average} kWh`);
    this._setFact("weekdayProfile", copy.weekdayProfile, attributes.weekday_profile_ready === true ? copy.profileReady : copy.profileMissing);
    this._setFact("weekendProfile", copy.weekendProfile, attributes.weekend_profile_ready === true ? copy.profileReady : copy.profileMissing);
    this._setFact("fallbackUsed", copy.fallbackUsed, attributes.fallback_currently_used === true ? copy.yes : copy.no);

    const physicalReady = attributes.physical_power_ready === true || attributes.physical_power_quality === "current";
    const readiness = {
      topology: available && inverterPower !== null && inverterCount !== null,
      batteryBms: attributes.bms_ready === true && capacity !== null,
      pvForecast: attributes.forecast_today_ready === true && attributes.forecast_tomorrow_ready === true,
      loadHistory: attributes.load_model_ready === true,
      physicalFlows: physicalReady,
      gridBattery: attributes.grid_to_battery_ready === true,
    };
    const readinessLabels = {
      topology: copy.topology,
      batteryBms: copy.batteryBms,
      pvForecast: copy.pvForecast,
      loadHistory: copy.loadHistory,
      physicalFlows: copy.physicalFlows,
      gridBattery: `${copy.gridBattery}: ${copy.providerless}`,
    };
    for (const [key, ready] of Object.entries(readiness)) {
      const ref = this._refs.readiness[key];
      const informational = key === "gridBattery" && !ready;
      ref.row.dataset.ready = informational ? "informational" : String(ready);
      ref.icon.textContent = informational ? "i" : ready ? "✓" : "!";
      ref.text.textContent = readinessLabels[key];
      ref.row.classList.toggle("shared-providerless", key === "gridBattery" && !ready);
    }

    const controlLabels = {
      inverterPower: copy.inverterPower,
      fallback: copy.fallback,
      forecastToday: `${copy.today} — ${copy.entityId}`,
      forecastTomorrow: `${copy.tomorrow} — ${copy.entityId}`,
      forecastDay3: `${copy.day3} — ${copy.entityId}`,
    };
    for (const [key, control] of Object.entries(this._refs.controls)) {
      control.label.textContent = controlLabels[key] || key;
      const entity = this._hass.states?.[control.entityId];
      control.input.disabled = !this._available(entity);
      if (control.type === "select") {
        const options = Array.isArray(entity?.attributes?.options)
          ? entity.attributes.options
          : [copy.automaticOption, "5 kW", "8 kW", "10 kW", "12 kW", "15 kW", "20 kW"];
        const currentOptions = Array.from(
          control.input.options,
          (option) => option.value
        );
        if (JSON.stringify(currentOptions) !== JSON.stringify(options)) {
          control.input.replaceChildren(...options.map((optionValue) => {
            const option = this._element("option", "", optionValue);
            option.value = optionValue;
            return option;
          }));
        }
      }
      if (entity && control.input.value !== String(entity.state)) {
        control.input.value = String(entity.state);
      }
    }
    this._patchFallbackVisibility(attributes);
    this._patchExpert(copy, attributes);
  }

  _patchFallbackVisibility(attributes = null) {
    if (!this._refs.fallbackWrapper || !this._hass) return;
    const broker = this._hass.states?.[this._config.shared_inputs_entity];
    const values = attributes || this._normalizeSharedContract(
      broker?.attributes || {}
    );
    this._refs.fallbackWrapper.hidden = false;
    const copy = HOYMILES_EMS_SHARED_INPUTS_C4_COPY[this._language()];
    this._refs.fallbackHelp.textContent = values.fallback_currently_used === true ||
      values.load_model_ready !== true
      ? copy.fallbackHelp
      : copy.fallbackNotUsed;
  }

  _patchExpert(copy, attributes) {
    const values = {
      entryId: attributes.config_entry_id || attributes.entry_id || copy.unknown,
      forecastTodayEntity: attributes.forecast_today_entity || copy.unknown,
      forecastTomorrowEntity: attributes.forecast_tomorrow_entity || copy.unknown,
      forecastDay3Entity: attributes.forecast_day_3_entity || copy.unknown,
      forecastRemainingEntity: attributes.forecast_remaining_today_entity || copy.unknown,
      pvPowerEntity: attributes.pv_power_entity || copy.unknown,
      homeLoadPowerEntity: attributes.home_load_power_entity || copy.unknown,
      systemLoadPowerEntity: attributes.system_load_power_entity || copy.unknown,
      batteryPowerEntity: attributes.battery_power_entity || copy.unknown,
      gridPowerEntity: attributes.grid_power_entity || copy.unknown,
      gridToBatteryPowerEntity: attributes.grid_to_battery_power_entity || copy.unknown,
      freshness: attributes.source_freshness || attributes.physical_power_freshness || copy.unknown,
      provenance: attributes.forecast_provenance || attributes.physical_power_provenance || copy.unknown,
      migration: `${attributes.migration_result || copy.unknown} · v${attributes.migration_version ?? 0}`,
      legacy: attributes.legacy_aliases || copy.unknown,
    };
    const labels = {
      entryId: "entry_id",
      forecastTodayEntity: "forecast_today_entity",
      forecastTomorrowEntity: "forecast_tomorrow_entity",
      forecastDay3Entity: "forecast_day_3_entity",
      forecastRemainingEntity: "forecast_remaining_today_entity",
      pvPowerEntity: "pv_power_entity",
      homeLoadPowerEntity: "home_load_power_entity",
      systemLoadPowerEntity: "system_load_power_entity",
      batteryPowerEntity: "battery_power_entity",
      gridPowerEntity: "grid_power_entity",
      gridToBatteryPowerEntity: "grid_to_battery_power_entity",
      freshness: copy.freshness,
      provenance: copy.provenance,
      migration: copy.migration,
      legacy: copy.legacy,
    };
    for (const [key, value] of Object.entries(values)) {
      this._refs.expertFields[key].term.textContent = labels[key];
      this._refs.expertFields[key].value.textContent =
        typeof value === "string" ? value : JSON.stringify(value);
    }
    const rawValues = {
      ...attributes.__raw,
    };
    this._refs.raw.textContent = JSON.stringify(rawValues, null, 2);
  }
}

if (!customElements.get("hoymiles-ems-shared-inputs-card")) {
  customElements.define(
    "hoymiles-ems-shared-inputs-card",
    HoymilesEmsSharedInputsCard
  );
}

if (!window.customCards.some((card) => card.type === "hoymiles-ems-shared-inputs-card")) {
  window.customCards.push({
    type: "hoymiles-ems-shared-inputs-card",
    name: "Hoymiles Shared EMS Inputs",
    description: "Entry-explicit shared EMS settings and compact status presentation.",
    preview: false,
  });
}

const HOYMILES_RCE_ZERO_EXPORT_ENTITIES = Object.freeze({
  plan: "sensor.hoymiles_hit_rce_optimized_plan",
  timeline: "sensor.hoymiles_hit_rce_automation_plan_timeline",
  controlConflict: "binary_sensor.hoymiles_ems_control_conflict",
});
const HOYMILES_RCE_ZERO_EXPORT_MAX_AGE_SECONDS = 300;
const HOYMILES_RCE_ZERO_EXPORT_FUTURE_TOLERANCE_SECONDS = 5;

function hoymilesRceTimestampFresh(value, nowMs = Date.now()) {
  const timestampMs = Date.parse(typeof value === "string" ? value : "");
  if (!Number.isFinite(timestampMs) || !Number.isFinite(nowMs)) return false;
  const ageSeconds = (nowMs - timestampMs) / 1000;
  return ageSeconds >= -HOYMILES_RCE_ZERO_EXPORT_FUTURE_TOLERANCE_SECONDS
    && ageSeconds <= HOYMILES_RCE_ZERO_EXPORT_MAX_AGE_SECONDS;
}

function hoymilesVerifiedRceZeroExportPlan(states, bindings = {}) {
  const planEntity = bindings.planEntity || HOYMILES_RCE_ZERO_EXPORT_ENTITIES.plan;
  const timelineEntity = bindings.timelineEntity || HOYMILES_RCE_ZERO_EXPORT_ENTITIES.timeline;
  const controlConflictEntity = bindings.controlConflictEntity
    || HOYMILES_RCE_ZERO_EXPORT_ENTITIES.controlConflict;
  const plan = states?.[planEntity];
  const timeline = states?.[timelineEntity];
  const conflict = states?.[controlConflictEntity];
  const planAttributes = plan?.attributes || {};
  const timelineAttributes = timeline?.attributes || {};
  const planState = String(plan?.state ?? "").trim().toLowerCase();
  const inputRevision = planAttributes.input_revision;
  const nowMs = typeof bindings.nowMs === "number" && Number.isFinite(bindings.nowMs)
    ? bindings.nowMs
    : Date.now();
  const planReportedAt = plan?.last_reported || plan?.last_updated || plan?.last_changed;
  const exactZero = (value) => typeof value === "number"
    && Number.isFinite(value)
    && value === 0;
  if (
    ["", "unknown", "unavailable", "none", "null", "nan"].includes(planState)
    || conflict?.state !== "off"
    || !hoymilesRceTimestampFresh(planReportedAt, nowMs)
    || !hoymilesRceTimestampFresh(timelineAttributes.generated_at, nowMs)
    || planAttributes.result_current !== true
    || planAttributes.recalculation_pending !== false
    || !Number.isInteger(inputRevision)
    || inputRevision < 0
    || planAttributes.gcf_execution_data_fresh !== true
    || planAttributes.gcf_enabled !== true
    || !exactZero(planAttributes.gcf_export_limit_percent)
    || !exactZero(planAttributes.planned_export_kwh)
    || !Array.isArray(planAttributes.planned_slots)
    || planAttributes.planned_slots.length !== 0
    || timeline?.state !== "current"
    || timelineAttributes.schema_version !== 2
    || timelineAttributes.policy_id !== "rce"
    || timelineAttributes.result_current !== true
    || timelineAttributes.recalculation_pending !== false
    || timelineAttributes.input_revision !== inputRevision
    || timelineAttributes.plan_entity_id !== planEntity
    || timelineAttributes.plan_revision_scope !== "runtime"
    || !Number.isInteger(timelineAttributes.plan_revision)
    || timelineAttributes.plan_revision < 1
    || !Number.isInteger(timelineAttributes.point_count)
    || timelineAttributes.point_count < 1
    || timelineAttributes.point_count > 192
    || !Array.isArray(timelineAttributes.points)
    || timelineAttributes.points.length !== timelineAttributes.point_count
  ) return false;
  return timelineAttributes.points.every((point) =>
    point && typeof point === "object" && !Array.isArray(point)
    && point.selected === false
    && point.action_code === "idle"
    && point.policy && typeof point.policy === "object" && !Array.isArray(point.policy)
    && exactZero(point.policy.planned_export_kwh)
  );
}

function hoymilesVerifiedTariffNoChargePlan(states, bindings = {}) {
  const planEntity = bindings.planEntity || "sensor.hoymiles_hit_tariff_charge_plan";
  const timelineEntity = bindings.timelineEntity
    || "sensor.hoymiles_hit_tariff_automation_plan_timeline";
  const controlConflictEntity = bindings.controlConflictEntity
    || HOYMILES_RCE_ZERO_EXPORT_ENTITIES.controlConflict;
  const plan = states?.[planEntity];
  const timeline = states?.[timelineEntity];
  const conflict = states?.[controlConflictEntity];
  const planAttributes = plan?.attributes || {};
  const timelineAttributes = timeline?.attributes || {};
  const planState = String(plan?.state ?? "").trim().toLowerCase();
  const inputRevision = planAttributes.input_revision;
  const nowMs = typeof bindings.nowMs === "number" && Number.isFinite(bindings.nowMs)
    ? bindings.nowMs
    : Date.now();
  const planReportedAt = plan?.last_reported || plan?.last_updated || plan?.last_changed;
  const exactZero = (value) => typeof value === "number"
    && Number.isFinite(value)
    && value === 0;
  if (
    ["", "unknown", "unavailable", "none", "null", "nan"].includes(planState)
    || conflict?.state !== "off"
    || !hoymilesRceTimestampFresh(planReportedAt, nowMs)
    || !hoymilesRceTimestampFresh(timelineAttributes.generated_at, nowMs)
    || planAttributes.status_code !== "no_charge_needed"
    || planAttributes.result_current !== true
    || planAttributes.recalculation_pending !== false
    || planAttributes.control_inputs_fresh !== true
    || !Number.isInteger(inputRevision)
    || inputRevision < 0
    || !Array.isArray(planAttributes.planned_slots)
    || planAttributes.planned_slots.length !== 0
    || !exactZero(planAttributes.planned_grid_import_kwh)
    || !exactZero(planAttributes.planned_stored_energy_kwh)
    || !exactZero(planAttributes.planned_direct_load_kwh)
    || timeline?.state !== "current"
    || timelineAttributes.schema_version !== 2
    || timelineAttributes.policy_id !== "tariff"
    || timelineAttributes.result_current !== true
    || timelineAttributes.recalculation_pending !== false
    || timelineAttributes.input_revision !== inputRevision
    || timelineAttributes.plan_entity_id !== planEntity
    || timelineAttributes.plan_revision_scope !== "runtime"
    || !["complete", "partial"].includes(timelineAttributes.quality)
    || !Number.isInteger(timelineAttributes.plan_revision)
    || timelineAttributes.plan_revision < 1
    || !Number.isInteger(timelineAttributes.point_count)
    || timelineAttributes.point_count < 1
    || timelineAttributes.point_count > 192
    || !Array.isArray(timelineAttributes.points)
    || timelineAttributes.points.length !== timelineAttributes.point_count
  ) return false;
  return timelineAttributes.points.every((point) =>
    point && typeof point === "object" && !Array.isArray(point)
    && point.selected === false
    && point.action_code === "idle"
    && point.policy && typeof point.policy === "object" && !Array.isArray(point.policy)
    && exactZero(point.policy.planned_import_kwh)
    && exactZero(point.policy.stored_energy_kwh)
    && exactZero(point.policy.direct_load_kwh)
    && exactZero(point.policy.planned_charge_kw)
  );
}

