    if(source.type==="supervisor"){
      const health=this._healthContract(state);
      return health.valid&&health.status!=="healthy";
    }
    if(source.type==="conflict")return ["on","unknown","unavailable"].includes(value);
    if(source.type==="readiness")return value!=="on";
