    set("[data-health-state]",this._healthStateText(status));
    const modalState=this._root?.querySelector("[data-health-state]");const modalReady=String(status==="healthy");if(modalState&&modalState.dataset.ready!==modalReady)modalState.dataset.ready=modalReady;if(modalState&&modalState.dataset.healthStatus!==status)modalState.dataset.healthStatus=status;
    set('[data-health-field="supervisor"]',health.phase);
    set('[data-health-field="reason"]',reason);
    set('[data-health-field="last-read"]',lastRead);
    set('[data-health-field="read-age"]',this._healthAgeText(health));
    set('[data-health-field="owner"]',ownerText);
    set('[data-health-field="stop"]',this._healthStopText(health));
    set('[data-health-field="connectivity"]',this._healthConnectivityText(health.connectivity));
    set('[data-health-field="rollback"]',health.rollbackStatus);
    set('[data-health-field="action"]',this._healthActionText(health.action));
    const current=this._currentFaults();
    const currentHtml=current.length
      ? current.map(item=>`<li><strong>${hoymilesEscape(item.label)}</strong><span>${hoymilesEscape(item.state)}${item.detail?` · ${hoymilesEscape(item.detail)}`:""}</span></li>`).join("")
      : `<li class="empty">${pl?"Brak aktywnych błędów falownika i EMS.":"No active inverter or EMS faults."}</li>`;
    const currentNode=this._root?.querySelector("[data-health-current]");
    if(currentNode&&currentNode.dataset.signature!==currentHtml){currentNode.dataset.signature=currentHtml;currentNode.innerHTML=currentHtml;}
    let historyHtml="";
