    const refresh=this._root?.querySelector("[data-health-refresh]");if(refresh&&refresh.disabled!==this._healthHistoryLoading)refresh.disabled=this._healthHistoryLoading;
    const busy=["clear_sending","restart_sending","restart_waiting"].includes(this._healthAction);
    const clear=this._root?.querySelector('[data-health-action="clear"]');
