  disconnectedCallback(){clearInterval(this._timer);this._timer=null;this._resize?.disconnect();this._request++;this._started=false;}
  _pl(){return String(this._hass?.locale?.language||this._hass?.language||"pl").startsWith("pl");}
  _t(pl,en){return this._pl()?pl:en;}
